/* Minimal htmx-compatible shim for stash's live search.
 *
 * This is NOT the full htmx library. It implements only the subset the stash
 * templates use: hx-get, hx-target, hx-trigger ("input changed delay:Nms" and
 * "search"), hx-indicator, and hx-headers (read from the <body> attribute).
 * The real htmx (https://htmx.org) is a drop-in superset: replacing this file
 * with the upstream htmx.min.js changes nothing in the markup.
 *
 * Live search is a progressive enhancement. With JS off, the search form still
 * submits as a normal GET to /search and the server renders a full page, so the
 * feature degrades rather than breaks.
 */
(function () {
  "use strict";

  function bodyHeaders() {
    var b = document.body;
    var raw = b && b.getAttribute("hx-headers");
    if (!raw) return {};
    try { return JSON.parse(raw); } catch (e) { return {}; }
  }

  function parseDelay(trigger) {
    var m = /delay:(\d+)ms/.exec(trigger || "");
    return m ? parseInt(m[1], 10) : 0;
  }

  function swap(el) {
    var url = el.getAttribute("hx-get");
    if (!url) return;
    var targetSel = el.getAttribute("hx-target");
    var target = targetSel ? document.querySelector(targetSel) : el;
    if (!target) return;
    var indSel = el.getAttribute("hx-indicator");
    var ind = indSel ? document.querySelector(indSel) : null;

    var q = el.value != null ? el.value : "";
    var full = url + (url.indexOf("?") === -1 ? "?" : "&") + "q=" + encodeURIComponent(q);

    var headers = bodyHeaders();
    headers["HX-Request"] = "true";

    if (ind) ind.classList.add("htmx-request");
    var xhr = new XMLHttpRequest();
    xhr.open("GET", full, true);
    Object.keys(headers).forEach(function (k) { xhr.setRequestHeader(k, headers[k]); });
    xhr.onload = function () {
      if (ind) ind.classList.remove("htmx-request");
      if (xhr.status >= 200 && xhr.status < 400) {
        target.innerHTML = xhr.responseText;
      }
    };
    xhr.onerror = function () { if (ind) ind.classList.remove("htmx-request"); };
    xhr.send();
  }

  function wire(el) {
    var trigger = el.getAttribute("hx-trigger") || "";
    var delay = parseDelay(trigger);
    var timer = null;

    function fire() {
      if (delay > 0) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(function () { swap(el); }, delay);
      } else {
        swap(el);
      }
    }

    if (/\binput\b/.test(trigger) || trigger === "") {
      el.addEventListener("input", fire);
    }
    if (/\bsearch\b/.test(trigger)) {
      el.addEventListener("search", function () { swap(el); });
    }
    if (/\bchange\b/.test(trigger)) {
      el.addEventListener("change", fire);
    }
  }

  function init() {
    var nodes = document.querySelectorAll("[hx-get]");
    for (var i = 0; i < nodes.length; i++) wire(nodes[i]);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
